package com.msarobotika.cyberdeck
import org.junit.Assert.*
import org.junit.Test
class AgentFollowupPolicyTest {
 private fun completed(plan:AgentPlan,inputs:AgentInputs=AgentInputs()):AgentSession {val steps=plan.steps.map{AgentStepResult(it,result=DiagnosticResult(it.wire,"own","old","fixture",emptyList()))};return AgentSession(request="Original",plan=plan,inputs=inputs,results=steps,run=AgentRun(plan,"old","end",steps),resumeEvidence=Evidence("id","name","hash",1,"at"),modelHash="model")}
 @Test fun followupsRecognizeOnlyAnExplicitSingleInstruction(){assertEquals(AgentFollowup.REPEAT,AgentFollowupPolicy.match("Repítelo."));assertEquals(AgentFollowup.SAVE,AgentFollowupPolicy.match("Guárdalo"));assertEquals(AgentFollowup.DETAILS,AgentFollowupPolicy.match("¿Cómo lo sabes?"));assertEquals(AgentFollowup.NEW,AgentFollowupPolicy.match("Nueva petición"));for(t in listOf("No lo repitas","Guárdalo y bórralo","Repite y envía archivos","haz lo que quieras"))assertNull(t,AgentFollowupPolicy.match(t))}
 @Test fun repeatStartsANewRunWithoutOldResultsSourceOrNetworkConsent(){val input=AgentInputs(url="https://example.com/Own",networkApproved=true);val next=AgentFollowupPolicy.repeated(completed(AgentPlan(listOf(AgentTool.WEB)),input))!!;assertEquals(input.url,next.inputs.url);assertFalse(next.inputs.networkApproved);assertNull(next.run);assertNull(next.resumeEvidence);assertTrue(next.results.isEmpty());assertEquals("Original",next.request);assertFalse(AgentFollowupPolicy.canRepeatImmediately(next))}
 @Test fun onlyLocalReadOnlyPhonePlansAreImmediate(){assertTrue(AgentFollowupPolicy.canRepeatImmediately(AgentSession(plan=AgentPlan(listOf(AgentTool.CONNECTION,AgentTool.RESOURCES)))));for(tool in listOf(AgentTool.BLE,AgentTool.NFC,AgentTool.WEB,AgentTool.FILES,AgentTool.TRANSFER,AgentTool.USB,AgentTool.EXPORT))assertFalse(tool.wire,AgentFollowupPolicy.canRepeatImmediately(AgentSession(plan=AgentPlan(listOf(tool))))) }
 @Test fun runningOrUnexecutedTasksCannotBeRepeated(){val s=completed(AgentPlan(listOf(AgentTool.CONNECTION)));assertNull(AgentFollowupPolicy.repeated(s.copy(running=true)));assertNull(AgentFollowupPolicy.repeated(s.copy(planning=true)));assertNull(AgentFollowupPolicy.repeated(s.copy(run=null)))}
 @Test fun repeatPreservesChosenToolsRatherThanAskingTheModelToInventNewOnes(){val plan=AgentPlan(listOf(AgentTool.PHONE,AgentTool.CONNECTION));val next=AgentFollowupPolicy.repeated(completed(plan))!!;assertEquals(plan,next.plan);assertEquals("model",next.modelHash);assertFalse(next.running);assertFalse(next.planning);assertTrue(next.contextSnapshot.isBlank())}
}
